import {TYPE_LABELS,CAPABILITIES,DEFAULT_FILTERS,filterEvents,moneyRows,ledgerGroups,buyerRows,paymentRows,paymentPurposeGroups,investorRows,snapshot,parseRoute,routeHash,PRICE_MODELS,estimatePrice,DEMAND_NEEDS,demandSnapshot} from './business-model.js';
import {evidenceUI} from './business-evidence.js';
import {analysisView,scenarioMarkup} from './business-analysis.js';
import {demandView} from './business-demand.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=parseRoute(location.hash);
const analysisParams=new URLSearchParams(location.hash.split('?')[1]||'');
const state={lang:'zh',view:route.view,filters:route.filters,limit:24,companyMode:'profiles',priceModel:'all',calcId:'price-witness-enterprise',quantity:500};
restoreAnalysis(analysisParams);
function restoreAnalysis(params){
  state.analysisTopic=params.get('topic')==='demand'?'demand':'pricing';
  state.demandNeed=Object.hasOwn(DEMAND_NEEDS,params.get('need'))?params.get('need'):'all';
  const model=params.get('analysisModel');state.priceModel=Object.hasOwn(PRICE_MODELS,model)?model:'all';
  state.calcId=params.get('component')||'price-witness-enterprise';
  const raw=params.get('quantity'),n=Number(raw);state.quantity=raw!==null&&raw!==''&&Number.isSafeInteger(n)&&n>=0&&n<=1e12?n:500;
}
function currentHash(){
  const hash=routeHash(state.view,state.filters);if(state.view!=='analysis')return hash;
  const p=new URLSearchParams(hash.split('?')[1]||'');
  if(state.analysisTopic==='demand'){p.set('topic','demand');if(state.demandNeed!=='all')p.set('need',state.demandNeed);return '#analysis?'+p.toString()}
  if(state.priceModel!=='all')p.set('analysisModel',state.priceModel);
  p.set('component',state.calcId);if(Number.isFinite(state.quantity))p.set('quantity',state.quantity);
  return '#analysis?'+p.toString();
}
try{state.lang=localStorage.getItem('atlas-language')==='en'?'en':'zh'}catch{}
let data,ui;
const t=(en,zh)=>state.lang==='en'?en:zh;
const tr=v=>esc(v&&typeof v==='object'?(v[state.lang]||v.en||v.zh||''):v);
const type=k=>TYPE_LABELS[k]?t(...TYPE_LABELS[k]):esc(k);
const cap=k=>CAPABILITIES[k]?t(...CAPABILITIES[k]):esc(k);
const co=id=>data.companies.find(c=>c.id===id);
const tabs=()=>({analysis:t('Data & insights','数据与分析'),activity:t('Industry pulse','产业动态'),money:t('Money flows','资金流向'),buyers:t('Buyers & demand','买方与需求'),companies:t('Organizations & investors','机构与投资者'),findings:t('Findings','发现与观察'),coverage:t('Coverage & gaps','覆盖与缺口')});
const validView=v=>Object.hasOwn(tabs(),v)||['reports','cases'].includes(v);
if(!validView(state.view))state.view='activity';
const badge=(v,kind='')=>'<span class="ep-badge '+kind+'">'+v+'</span>';
const detail=id=>'<button class="ep-text-button" data-detail="'+esc(id)+'">'+t('Evidence','查看证据')+' ↗</button>';
const link=s=>/^https:\/\//.test(s.url)?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title||s.url)+' ↗</a>':esc(s.title||s.url);
const cash=(v,currency='USD',compact=false,digits=0)=>v==null?t('Undisclosed','未披露'):new Intl.NumberFormat(state.lang==='zh'?'zh-CN':'en-US',{style:'currency',currency:currency||'USD',maximumFractionDigits:compact?2:digits,minimumFractionDigits:compact?0:digits,...(compact?{notation:'compact'}:{})}).format(v);
const empty=()=>'<div class="biz-empty"><h3>'+t('No records in this selection','当前筛选没有记录')+'</h3><p>'+t('This describes our collection, not the absence of activity in the market.','这说明当前收录范围内没有匹配项，不能据此认定市场中没有相关活动。')+'</p><button class="btn" data-reset>'+t('Reset filters','重置筛选')+'</button></div>';
const heading=(title,desc)=>'<div class="biz-heading"><h2>'+title+'</h2><p>'+desc+'</p></div>';
const metric=(name,value,note)=>'<div class="biz-metric"><span>'+name+'</span><strong>'+value+'</strong><small>'+note+'</small></div>';
const selected=()=>filterEvents(data,state.filters);

function allocation(value){return ({explicit_agent_security_line_item:t('Explicit agent-security module','明确的智能体安全模块'),model_security_in_agent_project:t('Model security within an agent project','智能体项目中的模型安全'),agent_safety_share_unknown:t('Agent Safety share unknown','Agent Safety 分摊比例未知')})[value]||t('Scope requires review','范围待核实')}
function basis(value){
  if(value==='department_reported_payment')return t('Government-reported payment · contract unmatched','政府披露付款 · 合同待匹配');
  if(value==='approximate_purchase_consideration_FY2025_20F')return t('FY2025 20-F · approximate total consideration','FY2025 20-F · 总对价约数');
  if(value==='award_line_item')return t('Award line item · payment unknown','中标分项 · 付款未知');
  if(value==='award_mixed_project')return t('Mixed project award · payment unknown','混合项目成交额 · 付款未知');
  if(value==='signed_mixed_contract')return t('Signed mixed-scope contract · payment unknown','混合服务合同额 · 付款未知');
  if(value==='approximate_net_cash_consideration')return t('Approximate net cash consideration','约数 · 净现金对价');
  if(value==='cash_consideration_FY2026_Q3_10Q_rounded')return t('FY2026 Q3 filing · cash consideration, rounded','FY2026 Q3 财报 · 现金对价约数');
  if(value==='single_funding_round')return t('Single round','单轮融资');
  if(value==='cumulative_funding_excluded_from_round_totals')return t('Historical cumulative amount · excluded from round totals','历史累计金额 · 不计入单轮合计');
  if(value==='eu_grant_contribution_not_disbursement')return t('EU grant contribution · payment not established','欧盟资助额 · 拨付情况未知');
  if(value==='separate_consideration_components')return t('Separate consideration components','对价分项披露');
  if(value==='cash_consideration_excluding_future_service_awards')return t('Cash consideration; future-service awards excluded','现金对价 · 不含未来服务奖励');
  if(value==='agreement_consideration_subject_to_adjustments')return t('Agreement amount, subject to adjustment','协议金额 · 可能调整');
  if(/fair_value/.test(value))return t('Fair value of consideration; preliminary','对价公允价值 · 暂定');
  if(/purchase_consideration/.test(value))return t('Purchase consideration in filing','财务披露的收购对价');
  return t('Amount not established in reviewed material','已读材料未确定金额');
}
function status(value){return ({award_announced:t('Award announced','已公告中标／成交'),contract_signed:t('Contract signed per notice','公告载明已签约'),completed:t('Completed','已完成'),announced:t('Announced','已公告'),announced_as_acquired:t('Announced as acquired','公告称已收购'),company_announced_raised:t('Company-announced funding','公司公告融资'),grant_agreement_signed:t('Grant agreement signed','资助协议签署')})[value]||t('Status requires verification','状态待核实')}
function level(k,detail){if(detail==='channel_deployment_account')return t('Channel deployment account','渠道部署叙述');if(detail==='named_buyer_statement_vendor_hosted')return t('Named buyer · vendor hosted','具名买方 · 供应商托管');return ({public_award:t('Public award notice','公共采购成交公告'),signed_contract:t('Signed contract record','已签署合同记录'),buyer_material:t('Buyer material','买方材料'),deployment_case:t('Vendor deployment account','厂商部署叙述'),evaluation_case:t('Evaluation-stage evidence','评估阶段证据'),project_report:t('Funded project report','资助项目报告')})[k]||esc(k)}
function summaryBar(events){
  const money=moneyRows(data,events),buyers=buyerRows(data,events);
  return '<div class="biz-metrics">'+metric(t('Selected activity','当前动态'),events.length,t('Events & dated / undated materials','事件与有／无日期材料'))+metric(t('Capital & grant disclosures','资金披露'),money.length,t('Transactions kept by type','按交易类型分别记账'))+metric(t('Buyer / adoption evidence','买方与采用证据'),buyers.length,t('Payment verified separately','是否付费另行核实'))+metric(t('Linked entities / consortia','关联主体／联合体'),new Set(events.flatMap(e=>e.companies)).size,t('Includes funders and acquired brands','包含资助机构与已收购品牌'))+'</div>';
}
function eventRows(events,limit=state.limit){
  return events.slice(0,limit).map(e=>'<article class="biz-event"><div class="biz-event-date"><strong>'+esc(e.date||t('Undated','日期未知'))+'</strong><small>'+t('Source / event date','材料／事件日期')+(e.datePrecision==='month'?t(' · month only',' · 月份精度'):e.datePrecision==='year'?t(' · year only',' · 年份精度'):'')+(e.dateBasis==='observed'?t(' · observed',' · 观察日期'):'')+'</small></div><div class="biz-event-body"><div class="ep-badges">'+badge(type(e.type))+e.companies.map(id=>'<button class="biz-company-link" data-company="'+esc(id)+'">'+esc(co(id)?.name)+'</button>').join('')+'</div><h3>'+esc(e.title)+'</h3><p>'+tr(e.summary)+'</p><div class="biz-event-bottom"><span>'+e.sources.length+' '+t('source links','个来源链接')+'</span>'+detail(e.detailId)+'</div></div>'+(e.amount!=null?'<div class="biz-event-amount">'+cash(e.amount,e.currency,true)+'<small>'+t('Disclosed · see basis','披露金额 · 见口径')+'</small></div>':'')+'</article>').join('');
}
function activity(events){
  const recent=moneyRows(data,events).filter(m=>m.type==='funding'&&m.amount!=null);
  const biggest=[...recent].sort((a,b)=>b.amount-a.amount).slice(0,4);
  return summaryBar(events)+'<div class="biz-pulse"><section class="biz-focus"><p class="ep-eyebrow">'+t('FOLLOW THE EVIDENCE','从证据看产业')+'</p><h2>'+t('Capital, customers,<br>and what comes next.','资本在投入什么，<br>买方在采用什么。')+'</h2><p>'+t('Follow a company from funding and product releases to buyer evidence. Every record retains its source and evidence boundary.','沿着融资、产品发布和买方证据，查看一家公司的变化。每条记录都保留来源与证据边界。')+'</p><div class="biz-actions"><button data-view="money">'+t('Explore the ledger','查看资金账本')+' →</button><button data-view="buyers">'+t('Inspect buyer evidence','查看买方证据')+' →</button></div></section><aside class="biz-spotlight"><p class="ep-eyebrow">'+t('SELECTED DISCLOSED ROUNDS','当前筛选 · 已披露单轮融资')+'</p>'+biggest.map(m=>'<button data-detail="'+esc(m.id)+'"><span>'+esc(co(m.companyId)?.name)+'<small>'+esc(m.date)+' · '+esc(m.round)+'</small></span><strong>'+cash(m.amount,m.currency,true)+'</strong></button>').join('')+(biggest.length?'':'<p>'+t('No disclosed rounds in this selection.','当前筛选没有已披露的融资轮次。')+'<p>')+'<small>'+t('Company-level funding; Agent Safety allocation unknown.','公司层面融资；Agent Safety 的分摊比例未知。')+'</small></aside></div>'+heading(t('Activity timeline','产业动态时间线'),t('Historical backfill is included. Undated pages retain their unknown publication date.','包含历史回填。没有发布日期的页面保留“日期未知”，不当作新发布。'))+'<div class="biz-timeline">'+(events.length?eventRows(events):empty())+'</div>'+(events.length>state.limit?'<button class="biz-load" data-more>'+t('Load more','加载更多')+' · '+Math.min(state.limit,events.length)+' / '+events.length+'</button>':'');
}
function moneyView(events){
  const rows=moneyRows(data,events),groups=ledgerGroups(rows);
  const streams=['funding','acquisition','grant','contract','cost','fund'];
  const counts=streams.map(k=>{const items=rows.filter(r=>r.type===k);return '<button class="biz-stream '+(state.filters.type===k?'selected':'')+'" data-type="'+k+'"><span>'+type(k)+'</span><strong>'+items.length+'</strong><small>'+t('collected events','条已收录事件')+'</small></button>'}).join('');
  const totals=groups.map(g=>'<div><span>'+type(g.type)+' · '+esc(g.currency)+'</span><strong>'+cash(g.total,g.currency)+'</strong><small>'+g.count+' '+t('disclosures','条披露')+(['acquisition','contract'].includes(g.type)?' · '+basis(g.basis):'')+(g.type==='contract'?' · '+allocation(g.allocation):'')+'</small></div>').join('');
  return heading(t('Six flows. Separate ledgers.','六类资金，分别记账。'),t('Totals below follow the current filters. Cumulative funding, currencies, procurement scope and acquisition accounting bases stay separate.','下方统计随筛选变化。累计融资、不同币种、采购范围和并购金额口径分别保留。'))+'<div class="biz-streams">'+counts+'</div><div class="biz-ledger-totals">'+totals+'</div><p class="ep-note">'+rows.filter(r=>r.amountStatus==='undisclosed').length+' '+t('events with undisclosed amounts','条金额未披露')+' · '+rows.filter(r=>r.amountStatus==='components_only').length+' '+t('component-only disclosures','条仅有对价分项')+' · '+rows.filter(r=>r.type==='funding_history').length+' '+t('cumulative disclosures excluded from round totals. Amounts cannot be interpreted as market size, customer spending or Agent-only investment.','条累计融资披露不计入单轮合计。金额不能解释为市场规模、客户支出或 Agent 专属投入。')+'</p>'+(rows.length?'<div class="ep-table-wrap"><table class="ep-table biz-money-table"><thead><tr>'+[t('Date & status','日期与状态'),t('Recipient / target','收款方／标的'),t('Type & amount','类型与金额'),t('Investors / buyer / acquirer','投资者／买方／收购方'),t('Evidence','证据')].map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(m=>'<tr><td><strong>'+esc(m.date)+'</strong><small>'+status(m.status)+'</small></td><td><button class="biz-company-link" data-company="'+esc(m.companyId)+'">'+esc(co(m.companyId)?.name)+'</button><small>'+esc(m.round==='Not stated'?t('Round not disclosed','轮次未披露'):m.round)+'</small></td><td>'+badge(type(m.type))+'<strong class="biz-table-amount">'+(m.amountStatus==='components_only'?t('See components','查看分项'):cash(m.amount,m.currency))+'</strong><small>'+basis(m.amountBasis)+'</small></td><td>'+(m.participants||[]).map(p=>'<span class="ep-investor-line">'+esc(p.name)+'</span>').join('')+'</td><td>'+detail(m.id)+'</td></tr>').join('')+'</tbody></table></div>':empty())+investors(rows);
}
function investors(rows){
  const all=investorRows(rows);
  if(!all.length)return '';
  return '<section class="ep-section">'+heading(t('Who backs or acquires whom','谁投资、谁收购'),t('Relationships follow the selected disclosures. Individual check sizes are unknown unless separately disclosed.','关系来自当前筛选的披露。未披露各自出资额时，不分摊交易总额。'))+'<div class="ep-investor-grid">'+all.map(p=>'<article class="ep-investor"><h3>'+esc(p.name)+'</h3>'+p.transactions.map(m=>'<button data-detail="'+esc(m.id)+'">'+esc(co(m.companyId)?.name)+'<small>'+esc(m.date)+' · '+({lead:t('Lead','领投'),participant:t('Participant','参与'),acquirer:t('Acquirer','收购方'),funder:t('Funder','资助方')})[m.role]+'</small></button>').join('')+'</article>').join('')+'</div></section>';
}
function buyersView(events){
  const rows=buyerRows(data,events),payments=paymentRows(data,events);
  return heading(t('Demand needs its own evidence','沿着买方证据理解需求'),t('A trial, deployment account, supplier listing and paid contract support different conclusions.','试点、部署叙述、供应商清单和付费合同，分别支持不同的结论。'))+'<div class="biz-metrics">'+metric(t('Buyer-origin materials','买方发布材料'),rows.filter(r=>['buyer_material','public_award','signed_contract'].includes(r.evidenceLevel)).length,t('Supplier status may be optional','供应商关系可能为可选'))+metric(t('Reported payment rows','官方披露付款'),payments.length,t('Contract matching tracked separately','合同匹配另行记录'))+metric(t('Disclosed purchase amounts','披露采购金额'),rows.filter(r=>r.procurementAmount!=null||r.contractAmount!=null).length,t('Unknown amounts stay unknown','缺失金额保留未知'))+metric(t('Verified renewals','已核实续约'),rows.filter(r=>r.renewalStatus==='verified').length,t('No inference from customer logos','客户 Logo 不能证明续约'))+'</div><div class="biz-research-note"><strong>'+t('Next evidence to seek','下一步需要的证据')+'</strong><p>'+t('Identify the budget owner, procurement criteria, paid scope, renewal and replacement decisions. Missing public evidence does not establish missing revenue.','补充预算负责人、采购门槛、付费范围、续约和替换决定。公开证据少，不能直接推断收入少。')+'</p></div><div class="ep-grid">'+rows.map(b=>'<article class="ep-card">'+badge(level(b.evidenceLevel,b.evidenceLevelDetail),['buyer_material','public_award','signed_contract'].includes(b.evidenceLevel)?'':'amber')+'<p class="ep-meta">'+esc(b.date||t('Undated','日期未知'))+(b.companyId?' · '+esc(co(b.companyId)?.name):'')+'</p><h3>'+esc(b.title)+'</h3><p>'+tr(b.summary)+'</p><div class="biz-proof-grid"><span>'+t('Payment','是否付费')+'<b>'+t('Unknown','未知')+'</b></span><span>'+t('Disclosed procurement amount','披露采购金额')+'<b>'+(b.procurementAmount!=null?cash(b.procurementAmount,b.currency):t('Unknown','未知'))+'</b></span><span>'+t('Renewal','续约情况')+'<b>'+t('Unknown','未知')+'</b></span></div><div class="ep-card-foot">'+detail(b.detailId)+'</div></article>').join('')+'</div>'+(rows.length||payments.length?'':empty())+paymentPurposeChart(payments)+paymentTable(payments);
}
function paymentPurposeChart(rows){
  if(!rows.length)return '';
  const groups=paymentPurposeGroups(rows),maxByCurrency={};
  for(const g of groups)maxByCurrency[g.currency]=Math.max(maxByCurrency[g.currency]||0,g.totalMinor);
  window.__bizPurposeEvidence=Object.fromEntries(groups.map(g=>[g.key,g.ids]));
  return '<section id="payment-purposes" class="ep-section">'+heading(t('Where selected spending is recorded','已选取支出的用途分布'),t('Grouped from the source Description field. These are department accounting labels; they do not identify product revenue or prove completed work.','根据原文 Description 字段归类。这些是部门记账标签，不能等同于产品收入或已完成的交付。'))+
    '<p class="ep-note">'+t('Follows current filters; each source line appears once. Unspecified use, operations and grants-unit services remain visible. The sample spans 2024–2025 and is not a complete budget or a growth comparison.','随当前筛选变化，每条源记录只计入一组。保留用途未细分、机构运营及资助部门服务。样本跨 2024–2025 年，不代表完整预算或增长比较。')+'</p><div class="biz-purpose-chart">'+groups.map(g=>'<button class="biz-purpose-row" data-purpose-evidence="'+esc(g.key)+'"><span class="biz-purpose-heading"><span>'+tr(g.label)+'</span><strong>'+cash(g.totalMinor/100,g.currency,false,2)+'</strong></span><span class="biz-purpose-track" aria-hidden="true"><span style="width:'+Math.max(0,100*g.totalMinor/maxByCurrency[g.currency]).toFixed(3)+'%"></span></span><small>'+g.ids.length+' '+t('source rows · inspect evidence','条源记录 · 查看证据')+' →</small></button>').join('')+'</div></section>';
}
function paymentTable(rows){
  if(!rows.length)return '';
  const totalMinor=rows.reduce((n,p)=>n+p.amountMinor,0);
  return '<section id="reported-payments">'+heading(t('Payments reported by the buyer','买方披露的付款明细'),t('Selected DSIT / AISI research, consultancy and technical-support rows. Each retains its transaction ID and source row; contracts and Agent Safety allocation remain unmatched.','选取 DSIT／AISI 的科研、咨询与技术支持付款行，保留交易编号和原始行号；对应合同与 Agent Safety 分摊比例仍待核实。'))+
    '<p class="ep-note">'+rows.length+' '+t('rows in this selection','条当前筛选记录')+' · '+cash(totalMinor/100,'GBP',false,2)+' · '+t('Do not add to contract values. A transaction may span several rows. Repeated rows do not establish renewals; this is not total AISI spending.','不与合同额相加；同一交易可有多条分项，付款行数不能证明续约，也不代表 AISI 全部支出。')+'</p><div class="ep-table-wrap"><table class="ep-table"><thead><tr>'+[t('Payment date','付款日期'),t('Recipient','接收方'),t('Disclosed amount','披露金额'),t('Reported purpose / category','原文用途／分类'),t('Evidence','证据')].map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(p=>'<tr><td>'+esc(p.date)+'</td><td><button class="biz-company-link" data-company="'+esc(p.companyId)+'">'+esc(co(p.companyId)?.name)+'</button><small>'+esc(p.transactionId)+'</small></td><td>'+cash(p.amount,p.currency,false,2)+'</td><td>'+tr(p.spendingPurpose.label)+'<small>'+esc(p.expenseType)+'</small></td><td>'+detail(p.id)+'</td></tr>').join('')+'</tbody></table></div></section>';
}
function companiesView(events){
  const ids=new Set(events.flatMap(e=>e.companies));
  const active=Object.entries(state.filters).some(([k,v])=>v!==DEFAULT_FILTERS[k]);
  const companies=data.companies.filter(c=>!active||ids.has(c.id)).sort((a,b)=>a.name.localeCompare(b.name));
  const sub='<div class="ep-subnav">'+[['profiles',t('Entity profiles','主体档案')],['investors',t('Investors & acquirers','投资机构与收购方')],['prices',t('Public prices','公开价格')]].map(([key,value])=>'<button data-mode="'+key+'" class="'+(state.companyMode===key?'active':'')+'">'+value+'</button>').join('')+'</div>';
  if(state.companyMode==='investors')return sub+investors(moneyRows(data,events));
  if(state.companyMode==='prices'){
    const picked=new Set(events.filter(e=>e.type==='price').map(e=>e.id));
    const priceUI=evidenceUI({...data,prices:data.prices.filter(p=>picked.has(p.id)),scenarios:active?[]:data.scenarios},state);
    return sub+priceUI.priceView();
  }
  return sub+heading(t('Companies, funders and procurement suppliers','公司、资助机构与采购承接方'),t('Capability tags describe the linked product portfolio; they do not allocate funding or certify effectiveness.','能力标签用于检索关联产品组合，不表示融资投向分配或效果认证。'))+'<p class="ep-result">'+companies.length+' '+t('profiles','个档案')+'</p><div class="ep-grid">'+companies.map(c=>'<article class="ep-card"><div class="ep-badges">'+badge(c.entityKind==='channel_partner'?t('Delivery / operations partner','交付／运营合作方'):c.entityKind==='buyer_platform'?t('Buyer / product platform','买方／产品平台'):c.entityKind==='payment_recipient'?t('Named payment recipient','披露付款接收方'):c.entityKind==='procurement_consortium'?t('Procurement consortium','采购联合体'):c.entityKind==='public_funder'?t('Public research funder','公共科研资助机构'):c.entityKind==='procurement_supplier'?t('Procurement supplier','采购承接机构'):c.entityKind==='acquired_company'?t('Acquired brand','已收购品牌'):c.scope==='related_business'?t('Relevant business line','相关业务线'):t('Company / brand','公司／品牌'),c.entityKind==='acquired_company'?'amber':'')+'</div><h3>'+esc(c.name)+'</h3>'+(c.owner?'<p class="ep-owner">'+t('Owner','所属方')+' · '+esc(c.owner)+'</p>':'')+'<p>'+tr(c.summary)+'</p><div class="ep-badges">'+c.capabilities.map(k=>badge(cap(k))).join('')+'</div><div class="ep-card-foot"><button class="ep-text-button" data-company="'+esc(c.id)+'">'+t('View timeline','查看时间线')+' · '+c.recordIds.length+'</button>'+detail(c.id)+'</div></article>').join('')+'</div>'+(companies.length?'':empty());
}
function findings(events){
  const money=moneyRows(data,events),buyers=buyerRows(data,events);
  const acquisitions=money.filter(r=>r.type==='acquisition');
  const acquirers=investorRows(acquisitions);
  const cashContracts=money.filter(r=>r.type==='contract');
  const funded=money.filter(r=>r.type==='funding');
  const cards=[
    {id:'capital-demand',kind:t('Collection finding','样本发现'),title:t('Compare capital and purchase evidence','对照资本披露与采购证据'),text:t('This selection contains '+funded.length+' funding events, '+buyers.length+' adoption / buyer materials and '+cashContracts.length+' procurement / contract disclosures.','当前筛选有 '+funded.length+' 条融资事件、'+buyers.length+' 条买方／采用材料、'+cashContracts.length+' 条采购／合同披露。'),limit:t('Collection imbalance is not evidence of weak demand. Private purchases may never be disclosed.','这可能反映采集偏向；私营采购可能不公开，不能据此判断需求弱。'),next:t('Seek buyer-controlled procurement, renewal and expansion records.','优先寻找买方发布的采购、续约和扩容记录。'),ids:[...funded.map(r=>r.id),...buyers.map(b=>b.detailId)]},
    {id:'consolidation',kind:t('Collection finding','样本发现'),title:t('Trace how capabilities enter larger platforms','追踪能力如何进入大型平台'),text:t(acquisitions.length+' acquisitions connect '+acquirers.length+' named acquirers to targets in this selection.','当前筛选中，'+acquisitions.length+' 条并购关联到 '+acquirers.length+' 个具名收购方。'),limit:t('An acquisition does not establish integration, revenue synergies or superior security.','收购不自动证明已完成产品整合、产生收入协同或提高安全效果。'),next:t('Follow post-acquisition releases, packaging and customer migration.','继续检查收购后的产品版本、套餐变化和客户迁移。'),ids:acquisitions.map(r=>r.id)},
    {id:'permissions',kind:t('Question to investigate','待验证方向'),title:t('Will tool permissions become a separate budget item?','工具权限会形成独立采购预算吗？'),text:t('Identity and MCP materials can be compared with buyer demands and platform offerings.','将身份、权限和 MCP 控制的产品材料，与买方要求和平台内置能力对照。'),limit:t('Product availability alone does not demonstrate willingness to pay.','有产品供给，还不能证明买方愿意独立付费。'),next:t('Look for explicit authorization requirements, evaluated alternatives and contract line items.','寻找明确的权限要求、评估过的替代方案和合同条目。'),ids:events.filter(e=>e.type==='product'&&e.capabilities.some(c=>['identity','mcp'].includes(c))).map(e=>e.id)},
    {id:'economics',kind:t('Question to investigate','待验证方向'),title:t('What does continuous protection cost in practice?','持续保护的实际成本是多少？'),text:t('Public prices and runtime-control materials give a starting point for comparable cost studies.','公开价格和运行时控制材料，可作为同口径成本比较的起点。'),limit:t('Units, deployment scope and excluded costs differ; list prices are not invoices.','计费单位、部署范围和不含费用不同；挂牌价不能当作客户账单。'),next:t('Collect real usage, review labor, latency budgets and annual commitments.','补充实际使用量、人工审核、延迟要求和年度承诺。'),ids:events.filter(e=>e.type==='price'||e.type==='product'&&e.capabilities.includes('runtime')).map(e=>e.id)}
  ];
  const lineItems=cashContracts.filter(r=>r.amountBasis==='award_line_item');
  const services=cashContracts.filter(r=>['research_service_supplier','joint_contracting_suppliers'].includes(r.supplierRole));
  if(cashContracts.length)cards.unshift(
    {id:'budget-lines',kind:t('Collection finding','样本发现'),title:t('Security can appear as a priced module within a larger project','安全模块可以在整包项目中单独列价'),text:t('This selection includes '+lineItems.length+' separately priced model / agent security items. Named contracting suppliers reveal the route through integrators.','当前筛选有 '+lineItems.length+' 条单独列价的模型／智能体安全条目。承接机构也展示了集成商参与采购的路径。'),limit:t('Line-item prices do not establish standalone sales, recurring revenue or payment. Scope differs between model security and agent-specific control.','条目价格不能证明独立销售、经常性收入或已付款；模型安全与 Agent 专属控制的范围不同。'),next:t('Track acceptance, maintenance, license duration and later expansion; link the supplier to the software owner only with evidence.','跟进验收、维保、许可期限与后续扩容；补充承接方与软件厂商之间的渠道证据。'),ids:lineItems.map(r=>r.id)},
    {id:'evaluation-demand',kind:t('Question to investigate','待验证方向'),title:t('Who pays for long-horizon agent evaluation and oversight?','谁会为长流程 Agent 的评测与监督付费？'),text:t(services.length+' research / testing procurements are visible here. Their requirements can guide work on realistic environments, continuous evaluation and reproducible assurance.','当前筛选包含 '+services.length+' 条研究／检测服务采购。其要求为真实环境、持续评测和可复现安全验证提供了需求线索。'),limit:t('These mixed-scope contracts do not establish agent-only spending or a market growth rate.','这些合同包含混合服务，不能据此计算 Agent 专属支出或市场增速。'),next:t('Extract deliverables and acceptance criteria; compare one-off testing with continuous monitoring and the cost of human review.','继续提取交付物与验收指标，对比一次性检测、持续监督和人工复核的成本。'),ids:services.map(r=>r.id)});
  const payments=paymentRows(data,events);
  if(payments.length)cards.unshift({id:'reported-payments',kind:t('Collection finding','样本发现'),title:t('Public spending reaches research and consultancy suppliers','公共支出已流向研发与咨询供应商'),text:t('This selection contains '+payments.length+' government-reported payment rows for '+new Set(payments.map(p=>p.companyId)).size+' named recipients.','当前筛选包含 '+payments.length+' 条政府披露付款，涉及 '+new Set(payments.map(p=>p.companyId)).size+' 个具名接收方。'),limit:t('Payment rows do not identify the contract, product, Agent-only allocation or renewal. The sample comes from one public buyer.','付款行未确定合同、产品、Agent 专属比例或续约；样本来自一个公共买方。'),next:t('Link transaction IDs to orders and deliverables; seek similar evidence from private buyers.','将交易编号与订单、交付物对应，并补充私人买方的同类证据。'),ids:payments.map(p=>p.id)});
  const buyerRequirements=buyers.filter(b=>b.detailId==='case-dropbox-lakera-buyer-2024');
  if(buyerRequirements.length)cards.unshift({id:'buyer-requirements',kind:t('Buyer-observed requirements','买方披露的要求'),title:t('Runtime protection must fit deployment constraints','运行时防护需要满足真实部署约束'),text:t('Dropbox describes internal hosting, low latency on long inputs, configurable confidence scores and testing security gains against the model baseline when selecting Lakera Guard.','Dropbox 在选择 Lakera Guard 时，要求内部部署、长输入低延迟和可调置信阈值，并相对模型原有防护评测新增安全收益。'),limit:t('One buyer account; no disclosed contract price or independently reproduced performance.','来自一个买方的自述；未披露合同价格，效果未经本站独立复现。'),next:t('Test private deployment, long-input latency and incremental attack prevention on realistic workflows; record false positives and operating cost.','围绕真实流程验证私有部署、长输入延迟和新增攻击拦截收益，同时记录误报与运行成本。'),ids:buyerRequirements.map(b=>b.detailId)});
  const embedded=buyers.filter(b=>['case-anaplan-noma-buyer-notice','case-uipath-noma-supplier-2025','case-twilio-lakera-subprocessor','case-thinkific-lakera-subprocessor','case-vanta-lakera-subprocessor'].includes(b.detailId));
  if(embedded.length)cards.unshift({id:'embedded-security',kind:t('Question to investigate','待验证方向'),title:t('Security may reach users through product suppliers','安全能力可能通过产品供应链进入企业'),text:t(embedded.length+' selected buyer records identify security suppliers and their product scope. These listings make embedded distribution relationships traceable.', '当前 '+embedded.length+' 条买方记录指明安全供应商及适用产品，可以沿产品集成路径追踪供应关系。'),limit:t('Targeted source selection is not market share. Listings do not establish payment, universal enablement, exclusivity or renewal.','定向采集不能推算市场份额；清单不代表已付款、所有客户启用、排他合作或续约。'),next:t('Track product scope, opt-in conditions, data-processing regions and later supplier replacements or removals.','跟进适用产品、启用条件、数据处理地区，以及后续供应商替换或移除。'),ids:embedded.map(b=>b.detailId)});
  const productExits=events.filter(e=>e.id==='lifecycle-twilio-ai-assistants-discontinued');
  if(productExits.length)cards.unshift({id:'buyer-product-lifecycle',kind:t('Collection finding','样本发现'),title:t('Track product exits alongside supplier listings','产品退出与供应商关系需要分别追踪'),text:t('Twilio marks AI Assistants as discontinued while its current list still names Lakera for AI products. Historical integration evidence alone cannot establish current product use.','Twilio 已标记 AI Assistants 停止服务，但现行 AI 产品分处理方清单仍列出 Lakera。历史集成材料不能单独证明当前产品仍在使用。'),limit:t('Shutdown date, cause, financial impact and supplier replacement are unknown. This does not establish the end of the wider supplier relationship.','停止日期、原因、财务影响和供应商替换均未知，不能据此认定双方整体合作终止。'),next:t('Follow product migration notices and revisions to supplier scope; verify paid renewals separately.','同时跟进产品迁移公告与供应商适用范围变化，再单独核实付费续约。'),ids:productExits.map(e=>e.id)});
  const architectureAssessment=events.filter(e=>e.id==='case-rasa-lakera-assessment-2025');
  if(architectureAssessment.length)cards.unshift({id:'architecture-control-evaluation',kind:t('Question to investigate','待验证方向'),title:t('Measure safeguards against architectural controls','把额外防护与架构约束放进同一评测'),text:t('Rasa provides a Lakera assessment and implementations for two mock agents. This supplies a concrete starting point for comparing control designs.','Rasa 提供两个模拟 Agent 的 Lakera 评测与实现，为对照不同控制设计提供了具体起点。'),limit:t('The evaluated systems excluded additional guardrails. One buyer-designed comparison does not establish general superiority or verified service revenue.','原评测未加入额外护栏；一个由买方设计的对照，不能证明普遍优越性或已产生服务收入。'),next:t('At comparable task utility, test workflow constraints, runtime screening and combinations; report attack outcomes, false blocks, latency and total cost.','在任务效用可比时，对照流程约束、运行时检测及两者组合；同时报告攻击结果、误拦、延迟和总成本。'),ids:architectureAssessment.map(e=>e.id)});
  const directed=payments.filter(p=>['autonomous_evaluations','safeguard_evaluations','evaluation_platform'].includes(p.spendingPurpose.id));
  if(directed.length)cards.unshift({id:'evaluation-spend-purpose',kind:t('Source-labelled spending','原文标注的支出'),title:t('Spending labels identify evaluation work','支出用途已具体到评测建设'),text:t(directed.length+' selected rows, totalling '+cash(directed.reduce((n,p)=>n+p.amountMinor,0)/100,'GBP',false,2)+', carry autonomous-system, safeguard or evaluation-platform labels.','当前 '+directed.length+' 条付款，合计 '+cash(directed.reduce((n,p)=>n+p.amountMinor,0)/100,'GBP',false,2)+'，原文用途标注为自主系统评测、安全防护评测或评测平台。'),limit:t('Accounting labels do not establish specific deliverables, contract links, acceptance or a complete budget.','记账标签未确定具体交付物、合同对应、验收或完整预算。'),next:t('Seek specifications and deliverables before linking this spending to specific evaluation products or research methods.','继续寻找规格与交付物，再将支出与具体评测产品或研究方法对应。'),ids:directed.map(p=>p.id)});
  const oversightAgenda=events.filter(e=>e.id==='programme-aisi-alignment-benchmarks');
  if(oversightAgenda.length)cards.unshift({id:'oversight-evaluation-agenda',kind:t('Question to investigate','待验证方向'),title:t('Make monitor failures measurable','把监督者失效转成可测问题'),text:t('AISI’s research agenda asks for partially observable oversight benchmarks, tests of monitor collusion and detection of rare attacks.','AISI 研究议程提出部分可观测监督基准、监督者串通评测及低概率攻击检测。'),limit:t('A public research priority is not a procurement award, market-size estimate or proof of demand from private buyers. No contract is matched to this agenda.','公共研究议程不等于采购授标、市场规模或私人买方需求；未与具体合同匹配。'),next:t('Test whether varied monitoring methods reduce shared misses under limited observation; report detection, false positives and cost.','检验不同监督方法能否在有限观测下减少共同漏报，并同时报告检测率、误报和成本。'),ids:oversightAgenda.map(e=>e.id)});
  const programmes=events.filter(e=>e.type==='programme');
  const trust=programmes.filter(e=>e.id==='programme-aria-scaling-trust-2026');
  const pivots=programmes.filter(e=>e.id==='programme-aria-pivot-2025');
  if(trust.length)cards.unshift({id:'public-coordination',kind:t('Question to investigate','待验证方向'),title:t('Who will adopt verifiable multi-agent coordination?','可验证的多 Agent 协调，谁会采用？'),text:t('ARIA’s Scaling Trust call supports shared coordination tooling and foundational security research. It offers a concrete public-R&D signal for this direction.','ARIA 的 Scaling Trust 征集公共协调工具与安全基础研究，为这一方向提供了明确的公共研发投入线索。'),limit:t('Programme budget is not awarded cash, private demand or market size.','计划预算不等于已授予资金、私人客户需求或市场规模。'),next:t('Track selected projects, delivery requirements, independent evaluations and deployment partners.','跟进获选项目、交付要求、独立评测和部署合作方。'),ids:trust.map(e=>e.id)});
  if(pivots.length)cards.unshift({id:'programme-pivots',kind:t('Collection finding','样本发现'),title:t('Follow changes in funding direction','同时追踪投入方向的调整'),text:t('ARIA stopped the former Safeguarded AI TA2 selection and redirected the programme. This is a documented change in technical priorities.','ARIA 停止原 Safeguarded AI TA2 遴选并调整计划，提供了一条技术优先级发生变化的记录。'),limit:t('This does not establish a programme-wide shutdown, a failed technology or a financial loss.','不能据此断定整个计划关闭、技术失败或发生财务损失。'),next:t('Check which successor calls lead to awards and completed outputs.','继续追踪后续征集实际授予了哪些项目、产出了什么成果。'),ids:pivots.map(e=>e.id)});
  window.__bizFindingEvidence=Object.fromEntries(cards.map(c=>[c.id,c.ids]));
  return heading(t('Findings that remain open to new evidence','让发现随着新证据更新'),t('Computed from the current selection. Research questions are explicitly marked and retain the evidence needed to test them.','基于当前筛选计算。待验证方向单独标记，并列出下一步需要的证据。'))+(state.filters.type!=='all'?'<p class="ep-note">'+t('A type filter excludes other evidence categories. Select all types before comparing capital and buyer evidence.','当前类型筛选排除了其他证据类别。比较资本与买方证据时，请选择全部类型。')+'</p>':'')+'<div class="biz-findings">'+cards.map(c=>'<article class="biz-finding">'+badge(c.kind,c.kind===t('Question to investigate','待验证方向')?'amber':'')+'<h3>'+c.title+'</h3><p>'+c.text+'</p><dl><dt>'+t('Alternative explanation / limit','替代解释／边界')+'</dt><dd>'+c.limit+'</dd><dt>'+t('What to check next','下一步如何验证')+'</dt><dd>'+c.next+'</dd></dl><button class="ep-text-button" data-evidence="'+c.id+'">'+t('Inspect supporting records','查看关联证据')+' · '+c.ids.length+' →</button></article>').join('')+'</div>';
}
function readiness(){
  const a=data.coverage.analysisReadiness;
  if(!a)return '';
  const m=a.metrics,audit=data.coverage.paymentSourceAudit;
  const list=items=>'<ul>'+items.map(v=>'<li>'+tr(v)+'</li>').join('')+'</ul>';
  return '<section id="analysis-readiness">'+heading(t('Is the data ready for analysis?','现在的数据够分析了吗？'),tr(a.headline))+
    '<div class="biz-metrics">'+metric(t('Money disclosures','资金披露'),m.moneyDisclosures,t('Collected records, not all market activity','已收录记录，非全部市场活动'))+metric(t('Procurement / contracts','采购／合同'),m.procurementRecords,t('Award and contract amounts','中标与合同金额'))+metric(t('Reported payment rows','官方披露付款'),m.reportedPaymentRows,t('Matched to contracts: ','已匹配合同：')+m.contractMatchedPaymentRows)+metric(t('Verified renewals','已核实续约'),m.verifiedRenewals,t('Public evidence gap','公开证据缺口'))+'</div>'+
    '<div class="biz-coverage-grid"><section class="biz-coverage-card"><h3>'+t('Supported now','目前可以支持')+'</h3>'+list(a.supported)+'</section><section class="biz-coverage-card"><h3>'+t('More evidence needed','仍需更多证据')+'</h3>'+list(a.unsupported)+'</section></div>'+
    '<div class="biz-research-note"><strong>'+t('Next step','下一步')+'</strong><p>'+tr(a.dashboardDecision)+'</p><p>'+m.unknownAgentAllocation+' / '+m.moneyDisclosures+' '+t('money records have no verified Agent Safety allocation.','条资金记录尚未确定 Agent Safety 分摊比例。')+'</p></div>'+
    (audit?'<p class="ep-note">'+t('Payment source check: ','付款来源核查：')+audit.sourceFileCount+' '+t('monthly CSVs, ','个月度 CSV，')+audit.sourceDataRows+' '+t('departmental rows, ','条部门记录，')+audit.aisiCandidateRows+' '+t('AISI candidates. Selected for publication: ','条 AISI 候选。已选取发布：')+audit.publishedSelectedRows+'；'+t('held for scope or identity evidence: ','待补范围或身份依据：')+(audit.heldForEvidenceRows||0)+'；'+t('outside this selected sample: ','不纳入当前样本：')+(audit.excludedSelectedScopeRows||0)+t('. Triage is complete; held records still need verification.','. 已完成初筛，暂存记录仍需核实。')+'</p>':'')+
    '<details class="biz-disclosure"><summary>'+t('Collection priorities, channels and how to organize them','补什么、从哪找、怎样整理')+' · '+a.gaps.length+'</summary><div class="biz-gap-grid">'+a.gaps.map(g=>'<article class="biz-coverage-card">'+badge(g.priority)+'<h3>'+tr(g.title)+'</h3><p>'+tr(g.needed)+'</p><p><strong>'+t('Sources: ','渠道：')+'</strong>'+tr(g.channels)+'</p><p><strong>'+t('Method: ','整理：')+'</strong>'+tr(g.method)+'</p></article>').join('')+'</div></details>'+
    '<details class="biz-disclosure"><summary>'+t('Conditions for broader analytics','扩展分析版面的条件')+'</summary><div class="biz-readiness-criteria">'+list(a.releaseCriteria)+'<p>'+t('Readiness assessed on ','评估日期：')+esc(a.assessedOn)+t('; counts are recomputed from this dataset.','；上方数量随数据构建重新计算。')+'</p></div></details></section>';
}
function coverage(){
  const c=data.coverage,applied=c.patchReceipts.filter(r=>r.status==='applied_projection').length;
  const complete=c.sourceChecks.filter(s=>s.status==='complete_for_defined_source').length;
  return readiness()+heading(t('See what is covered. See what remains unknown.','覆盖到哪里，还有哪些未知。'),t('This page describes the full dataset, independent of event filters. Global coverage has not been measured.','本页展示全库覆盖状态，不受动态筛选影响。全行业覆盖率尚未测量。'))+'<div class="biz-metrics">'+metric(t('Linked source URLs','已关联来源链接'),c.sourceURLCount,t('Deduplicated URLs; not independent confirmations','URL 去重；不等于独立确认数'))+metric(t('Historical materials integrated','历史材料已整合'),c.historicalMaterialCount,t('Baseline, reviewed batches and targeted rechecks','包含基线、阶段审阅与定点复核'))+metric(t('Corrections in this view','本视图生效修正'),applied+' / '+c.patchReceipts.length,t('Frozen inputs retained','保留冻结原始材料'))+metric(t('Pending records','待核实材料'),c.queue.length,t('Excluded from published event totals','不计入正式动态合计'))+'</div><div class="biz-coverage-grid"><section class="biz-coverage-card"><h3>'+t('Dates and evidence scope','日期与证据范围')+'</h3><dl class="ep-facts"><div><dt>'+t('Historical batches','历史批次')+'</dt><dd>'+c.historicalCutoff+'</dd></div><div><dt>'+t('Pilot cut-off','原商业页资料截止')+'</dt><dd>'+c.pilotCutoff+'</dd></div><div><dt>'+t('Targeted source recheck','部分来源定点复核')+'</dt><dd>'+c.lastTargetedVerification+'</dd></div><div><dt>'+t('Global recall','全行业事件召回率')+'</dt><dd>'+t('Not measured','尚未测量')+'</dd></div><div><dt>'+t('Geographic coverage','地区覆盖率')+'</dt><dd>'+t('Not measured','尚未测量')+'</dd></div></dl><p>'+t('Recent rechecks do not mean every source is current. Selected B007/B008 transactions received source rechecks; remaining records still await review.','部分来源复核不表示全库已更新到当天。B007／B008 的部分交易已定点复核，其余材料仍待审阅。')+'</p></section><section class="biz-coverage-card"><h3>'+t('Where to expand next','下一步补充重点')+'</h3><ul><li>'+t('Buyer contracts, renewals and cancellations','买方合同、续约和取消')+'</li><li>'+t('China and other regional sources; multilingual discovery','中国及其他地区来源、多语言发现')+'</li><li>'+t('Company exits, pivots and discontinued products','公司退出、转型和产品下线')+'</li><li>'+t('Independent recall audits and source freshness','独立召回审计与来源新鲜度')+'</li></ul><p>'+t('Daily discovery and the Monday/Thursday updater rotate through registered sources. Each run checks up to eight sources; daily discovery also prepares up to four candidate pages for review.','每日发现与每周一、四的更新流程轮巡登记来源。每轮检查最多 8 个来源；每日发现另准备最多 4 个候选页面，供后续核实。')+'</p></section></div>'+monitoring() +heading(t('Source coverage ledger','已检查来源与范围'),t(complete+' of '+c.sourceChecks.length+' historical source-range entries are marked complete within their own boundaries. This is not a market coverage percentage.',c.sourceChecks.length+' 条历史来源范围记录中，'+complete+' 条标记为其限定范围内完成；这不是市场覆盖率。'))+'<details class="biz-disclosure"><summary>'+t('Inspect source ranges and limits','展开查看来源范围与限制')+'</summary><div class="ep-table-wrap"><table class="ep-table"><thead><tr><th>'+t('Source','来源')+'</th><th>'+t('Checked range','已检查范围')+'</th><th>'+t('Status / limits','状态／限制')+'</th></tr></thead><tbody>'+c.sourceChecks.map(s=>'<tr><td>'+link({url:s.url,title:co(s.companyId)?.name||s.sourceCategory})+'</td><td>'+esc(s.checkedRange)+'<small>'+t('Requested','目标范围')+' '+esc(s.requestedWindow)+'</small></td><td>'+esc(s.status)+'<small>'+esc(s.limitations||s.nextCursor)+'</small></td></tr>').join('')+'</tbody></table></div></details>'+heading(t('Sources planned for expansion','扩展来源清单'),t('Integration state is tracked per source; documentation alone does not establish a working feed.','逐项记录接入状态；已阅读文档的来源仍需验证，英国采购增量接口已接通。'))+'<div class="ep-grid">'+data.sourcePlan.map(s=>'<article class="biz-source"><span>'+esc(s.region)+' · '+esc(s.priority)+'</span><h3>'+esc(s.source_name)+'</h3><p>'+esc(s.access_requirements.replaceAll('_',' '))+'</p>'+link({url:s.entry_url,title:t('Source & access documentation','来源与接入说明')})+'</article>').join('')+'</div><details class="biz-disclosure"><summary>'+t('Pending evidence','待核实材料')+' · '+c.queue.length+'</summary>'+c.queue.map(r=>'<div class="biz-queue"><span>'+esc(r.batchId)+' · '+(r.reason==='working_batch'?t('Unfinished batch','未完成批次'):t('Pending stage review','待阶段审阅'))+'</span>'+link({url:r.url,title:r.title})+'</div>').join('')+'</details><details class="biz-disclosure"><summary>'+t('Correction receipts','修正记录')+' · '+c.patchReceipts.length+'</summary>'+c.patchReceipts.map(r=>'<div class="biz-queue"><span>'+esc(r.id)+' · '+(r.status==='applied_projection'?t('Applied to derived view','已在派生视图生效'):t('Pending','待处理'))+'</span><p>'+esc(r.reason)+'</p></div>').join('')+'</details>';
}
function monitoring(){
  const m=data.coverage.sourceMonitoring;
  if(!m)return '';
  const pending=m.changeQueue||[],candidates=m.discoveryQueue||[];
  const totalScanned=m.entriesScanned||0;
  return heading(t('Incremental collection & review queue','增量采集与待核实线索'),esc(m.checkedAt)+' · '+t('Fetching and discovery do not verify a claim.','获取和发现不代表事实已经核实。'))+
    '<div class="biz-metrics">'+metric(t('Requests this run','本轮请求'),m.checkedThisRun,m.successThisRun+' '+t('successful','成功'))+metric(t('Entries scanned','扫描条目'),totalScanned,t('Directory, feed and procurement entries','目录、订阅与采购公告条目'))+metric(t('New URLs this run','本轮新链接'),m.newURLsThisRun||0,t('First inventory may contain historical items','首次建库可能包含历史材料'))+metric(t('Conditional cache hits','条件缓存命中'),m.notModifiedThisRun||0,t('304 responses avoid body downloads','304 响应省去正文下载'))+'</div>'+
    '<p class="ep-note">'+t('Downloaded this run: ','本轮下载：')+((m.bytesDownloaded||0)/1024).toFixed(0)+' KB · '+t('Avoided with cache: ','缓存省去：')+((m.bytesAvoided||0)/1024).toFixed(0)+' KB · '+t('Registered sources: ','已登记来源：')+m.watchlistCount+' · '+t('Pending candidate URLs: ','待核实候选链接：')+(m.pendingCandidates||0)+'</p>'+
    '<details class="biz-disclosure"><summary>'+t('Inspect collection status and pagination','查看采集状态与分页进度')+'</summary>'+m.checks.map(c=>'<div class="biz-queue"><span>'+esc(c.checkedAt)+' · '+({fetched:t('Fetched','获取成功'),not_modified:t('Not modified · cached','未变化 · 使用缓存'),failed:t('Fetch failed','获取失败')})[c.status]+' · '+esc(c.adapter||'html')+'</span>'+link(c)+(c.window?'<p>'+esc(c.window.start)+' → '+esc(c.window.end)+' · '+(c.nextURL?t('Window incomplete; next cursor saved','时间窗尚未扫完，已保存下一页位置'):t('Window scan completed','该时间窗已扫描完成'))+'</p>':'')+'</div>').join('')+'</details>'+
    '<details class="biz-disclosure"><summary>'+t('Candidate links awaiting review','待核实候选链接')+' · '+(m.pendingCandidates||0)+'</summary><p class="ep-note">'+t('Shows up to 100 candidates, with buyer sources first. Candidates may be irrelevant and are excluded from published activity.','最多展示 100 条，优先显示买方来源。候选可能不相关，不计入已核实动态。')+'</p>'+candidates.map(c=>'<div class="biz-queue"><span>'+esc(c.firstSeen.slice(0,10))+' · '+(c.priority==='buyer'?t('Buyer source','买方来源'):c.priority==='transaction'?t('Possible transaction · unverified','疑似交易 · 待核实'):t('Company source','企业来源'))+'</span>'+link(c)+'</div>').join('')+'</details>'+
    (pending.length?'<details class="biz-disclosure"><summary>'+t('Changed pages awaiting review','页面变化待核实')+' · '+pending.length+'</summary>'+pending.map(c=>'<p>'+link(c)+'</p>').join('')+'</details>':'');
}

function archive(events){
  const ids=new Set(events.map(e=>e.id));
  const rows=data[state.view].filter(r=>ids.has(r.id));
  return heading(state.view==='reports'?t('Reports & historical analysis','报告与历史分析'):t('Incidents & cases','事件与案例'),t('Original evidence types and limitations are retained.','保留原始证据类型与适用边界。'))+'<div class="ep-grid">'+rows.map(r=>ui.card(r,state.view)).join('')+'</div>'+(rows.length?'':empty());
}
function analysisPanel(events){
  const sub='<div class="ep-subnav" aria-label="'+t('Analysis topic','分析主题')+'">'+[['pricing',t('Pricing & cost','收费方式与成本')],['demand',t('Buyer needs & channels','买方需求与渠道')]].map(([key,label])=>'<button data-analysis-topic="'+key+'" aria-pressed="'+(state.analysisTopic===key)+'" class="'+(state.analysisTopic===key?'active':'')+'">'+label+'</button>').join('')+'</div>';
  return sub+(state.analysisTopic==='demand'?demandView(data,events,state):analysisView(data,events,state));
}
function content(){
  if(state.view==='coverage')return coverage();
  const events=selected();
  return ({analysis:analysisPanel,activity,money:moneyView,buyers:buyersView,companies:companiesView,findings,reports:archive,cases:archive})[state.view](events);
}
function selectControl(key,label,options){
  return '<label class="ep-select"><span>'+label+'</span><select data-filter="'+key+'"><option value="all">'+t('All','全部')+'</option>'+options.map(([id,title])=>'<option value="'+esc(id)+'" '+(state.filters[key]===id?'selected':'')+'>'+esc(title)+'</option>').join('')+'</select></label>';
}
function toolbar(){
  if(state.view==='coverage')return '';
  return '<section class="biz-toolbar" aria-label="'+t('Filter activity','筛选动态')+'"><div class="biz-filter-main"><label class="ep-search"><span>'+t('Search companies, investors or topics','搜索公司、投资机构或主题')+'</span><input id="biz-search" type="search" value="'+esc(state.filters.query)+'" placeholder="'+t('e.g. permissions, Zenity, ClearSky','如：权限、Zenity、ClearSky')+'"></label>'+selectControl('type',t('Activity type','动态类型'),Object.keys(TYPE_LABELS).map(k=>[k,type(k)]))+selectControl('company',t('Entity / consortium','主体／联合体'),data.companies.map(c=>[c.id,c.name]).sort((a,b)=>a[1].localeCompare(b[1])))+'</div><details class="biz-advanced" '+(state.filters.from||state.filters.to||state.filters.capability!=='all'?'open':'')+'><summary>'+t('Dates & capabilities','日期与能力筛选')+'</summary><div class="biz-filter-extra"><label class="ep-select"><span>'+t('From','起始日期')+'</span><input type="date" data-filter="from" value="'+esc(state.filters.from)+'"></label><label class="ep-select"><span>'+t('To','结束日期')+'</span><input type="date" data-filter="to" value="'+esc(state.filters.to)+'"></label>'+selectControl('capability',t('Record / company capability','记录／公司能力标签'),Object.keys(CAPABILITIES).map(k=>[k,cap(k)]))+'<label class="biz-check"><input type="checkbox" data-filter="undated" '+(state.filters.undated?'checked':'')+'>'+t('Include undated records in date windows','日期筛选保留无日期记录')+'</label></div><p>'+t('Month/year-only dates match overlapping windows. Explicit record scope takes priority; other records use company capability tags. Tags do not allocate funding.','仅有月份／年份的日期按区间相交匹配。已标注的记录使用自身范围，其余采用公司能力标签；标签不代表资金分配。')+'</p></details><div class="biz-filter-actions"><span id="biz-filter-count" role="status"></span><button data-reset>'+t('Reset','重置')+'</button><button data-share>'+t('Copy view link','复制当前视图链接')+'</button><button data-export>'+t('Export selection','导出当前筛选')+' ↓</button></div></section>';
}
function renderContent(){
  $('#ep-content').innerHTML=content();
  const count=$('#biz-filter-count');
  if(count)count.textContent=state.filters.from&&state.filters.to&&state.filters.from>state.filters.to?t('Start must not be after end.','起始日期不能晚于结束日期。'):selected().length+' '+t('matching activity records','条匹配动态');
  history.replaceState(null,'',currentHash());
}
function render(){
  document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';
  document.title=t('Industry & Money | Agent Safety Atlas','产业与资金 | Agent Safety Atlas');
  const nav=Object.entries(tabs()).map(([key,title])=>'<button role="tab" id="tab-'+key+'" aria-controls="ep-panel" aria-selected="'+(key===state.view)+'" tabindex="'+(key===state.view?'0':'-1')+'" data-view="'+key+'" class="'+(key===state.view?'active':'')+'">'+title+'</button>').join('');
  $('#app').innerHTML='<header class="ep-header"><a class="brand" href="./"><span class="biz-mark">X</span><span>Agent Safety Atlas<small>'+t('INDUSTRY & MONEY','产业与资金观察')+'</small></span></a><div class="ep-header-actions"><a href="./#insights">'+t('Research insights','研究洞察')+' ↗</a><button data-view="reports">'+t('Reports','报告')+'</button><button data-view="cases">'+t('Cases','案例')+'</button><button id="biz-language" class="language-switch">'+t('中文','English')+'</button></div></header><main class="ep-main"><section class="ep-hero"><div><p class="ep-eyebrow">'+t('THE BUSINESS OBSERVATORY','AGENT SAFETY · 商业观察')+'</p><h1>'+t('Follow the money.<br>Understand the industry.','追踪资金流向，<br>理解产业变化。')+'</h1><p class="ep-intro">'+t('Funding, acquisitions, products and buyer evidence — connected to their original sources.','连接融资、并购、产品与买方证据，持续追踪背后的机构、需求和变化。')+'</p></div><aside class="ep-pilot"><span>'+t('OBSERVATION SCOPE','当前观察范围')+'</span><strong>'+data.companies.length+' '+t('entities / consortia','个主体／联合体')+' · '+data.events.length+' '+t('activity records','条动态')+'</strong><p>'+t('Public evidence · curated coverage','公开证据 · 持续补充')+'</p><small>'+t('Historical data through','历史资料截止')+' '+data.meta.cutoff+'<br>'+t('Targeted rechecks','部分来源复核')+' '+data.coverage.lastTargetedVerification+'</small><button class="ep-text-button" data-view="coverage">'+t('Inspect coverage & gaps','查看覆盖与缺口')+' →</button></aside></section><nav class="ep-tabs" role="tablist" aria-label="'+t('Business views','商业栏目')+'">'+nav+'</nav><section id="ep-panel" '+(Object.hasOwn(tabs(),state.view)?'role="tabpanel" aria-labelledby="tab-'+state.view+'"':'aria-label="'+t('Evidence archive','证据档案')+'"')+'>'+toolbar()+'<div id="ep-content"></div></section><footer class="ep-footer"><p>'+t('Collected public evidence, with unknown amounts and incomplete coverage retained. Financing, contracts, payment records and safety effectiveness require separate evidence.','基于已收录的公开证据，保留未知金额与覆盖缺口。融资、合同、付款和安全效果分别取证。')+'</p><a href="./data/business.json" download>JSON ↓</a><a href="./data/business-money.csv" download>'+t('Money ledger','资金账本')+' CSV ↓</a><a href="./data/business-payments.csv" download>'+t('Payment records','付款明细')+' CSV ↓</a><a href="./business-report-2026-09-12.html">'+t('September 12 report snapshot','9 月 12 日历史报告')+' ↗</a></footer></main><dialog id="ep-dialog" aria-labelledby="ep-detail-title"><button class="close" id="ep-close" aria-label="'+t('Close','关闭')+'">×</button><div class="detail" id="ep-detail"></div></dialog><div id="biz-toast" role="status"></div>';
  renderContent();
  $('#biz-language').onclick=()=>{state.lang=state.lang==='zh'?'en':'zh';try{localStorage.setItem('atlas-language',state.lang)}catch{}render()};
  $('#biz-search')?.addEventListener('input',e=>{state.filters.query=e.target.value;state.limit=24;renderContent()});
  document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change',()=>{state.filters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;state.limit=24;renderContent()}));
  $('#ep-close').onclick=()=>$('#ep-dialog').close();
  $('.ep-tabs').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(tabs());let i=keys.indexOf(state.view);i=e.key==='Home'?0:e.key==='End'?keys.length-1:(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length;setView(keys[i]);$('#tab-'+keys[i]).focus()};
}
function setView(view){if(!validView(view))return;state.view=view;state.limit=24;render()}
function show(html){$('#ep-detail').innerHTML=html;if(!$('#ep-dialog').open)$('#ep-dialog').showModal()}
function showDetail(id){
  const m=data.materials.find(r=>r.id===id);
  if(m){show('<p class="ep-meta">'+esc(m.date||t('Undated','日期未知'))+(!m.date&&m.observedOn?' · '+t('Observed ','观察日期 ')+esc(m.observedOn):'')+' · '+esc(m.batchId)+' · '+(m.reviewStatus==='targeted_primary_source_recheck'?t('Selected fields rechecked against primary source','关键字段已对照一手来源复核'):t('Limited stage review','有限阶段审阅'))+'</p><h2 id="ep-detail-title">'+esc(m.title)+'</h2><p>'+tr(m.summary)+'</p><div class="ep-detail-note"><strong>'+t('Scope and attribution','范围与归属')+'</strong><p>'+tr(m.scopeReason)+'</p><p>'+t('Source-attributed material. Product performance and commercial claims have not been independently reproduced.','保留原始来源归属；产品效果与商业主张未经独立复现。')+'</p></div><h3>'+t('Original sources','原始来源')+'</h3>'+m.sources.map(s=>'<div class="evidence">'+link(s)+'</div>').join(''));return}
  const r=[...data.companies,...data.money,...data.payments,...data.cases,...data.reports,...data.prices].find(r=>r.id===id);
  if(!r)return;
  if(r.type==='payment'){
    show('<p class="ep-meta">'+esc(r.date)+' · '+t('Government-reported payment','政府披露付款')+'</p><h2 id="ep-detail-title">'+esc(r.title)+'</h2><p>'+tr(r.summary)+'</p><dl class="ep-facts">'+[[t('Amount','金额'),cash(r.amount,r.currency,false,2)],[t('Buyer','付款部门'),r.buyer],[t('Supplier as published','原文供应商名称'),r.supplier],[t('Transaction ID','交易编号'),r.transactionId],[t('Purpose label','原文用途分类'),r.spendingPurpose.label[state.lang]],[t('Expense category','支出分类'),r.expenseType],[t('Original description','原文用途描述'),r.reportedDescription],[t('Contract match','合同关联'),t('Unmatched','尚未匹配')],[t('Source row','CSV 行号'),r.sourceRow]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><h3>'+t('Evidence boundaries','证据边界')+'</h3><p>'+tr(r.limitations)+'</p><h3>'+t('Original sources','原始来源')+'</h3>'+r.sources.map(v=>'<div class="evidence">'+link(v)+'<small>'+esc(v.locator)+'</small></div>').join(''));return;
  }
  let extra='';
  if(r.jointSupplierMembers?.length)extra+='<h3>'+t('Joint suppliers · one award','联合体成员 · 一笔成交额')+'</h3><ul>'+r.jointSupplierMembers.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul>';
  if(r.amountBasis){
    extra+='<div class="ep-detail-note"><strong>'+t('Amount basis','金额口径')+'</strong><p>'+basis(r.amountBasis)+'</p><p>'+allocation(r.allocation)+'</p></div>';
    if(r.type==='contract')extra+='<dl class="ep-facts"><div><dt>'+t('Buyer','采购方')+'</dt><dd>'+esc(r.buyer)+'</dd></div><div><dt>'+t('Project ID','项目编号')+'</dt><dd>'+esc(r.procurementId)+'</dd></div>'+(r.lineItemId?'<div><dt>'+t('Item / contract ID','条目／合同编号')+'</dt><dd>'+esc(r.lineItemId)+'</dd></div>':'')+(r.parentAwardAmount!=null?'<div><dt>'+t('Whole project · excluded from totals','整包项目 · 不重复计入')+'</dt><dd>'+cash(r.parentAwardAmount,r.currency)+'</dd></div>':'')+'<div><dt>'+t('Actual payment','实际付款')+'</dt><dd>'+t('Unknown','未知')+'</dd></div></dl>';
    const parts=r.originalAttributes?.consideration;
    if(parts)extra+='<h3>'+t('Disclosed components','披露的对价分项')+'</h3><p>'+t('Cash, net of acquired cash','扣除取得现金后的现金对价')+'：'+cash(parts.cash_net_of_acquired_cash,parts.currency)+'</p><p>'+t('Replacement awards for pre-acquisition service','收购前服务对应替代股权奖励')+'：'+cash(parts.replacement_equity_awards_pre_acquisition_service_fair_value,parts.currency)+'</p>';
  }
  show(ui.detailMarkup(r)+extra);
}
function exportSelection(){
  const result=snapshot(data,state.filters);
  if(state.view==='analysis'&&state.analysisTopic==='demand'){result.analysis={topic:'demand',...demandSnapshot(data,selected(),state.demandNeed)};return result}
  if(state.view==='analysis')result.analysis={priceModel:state.priceModel,visiblePriceIds:result.prices.filter(p=>state.priceModel==='all'||p.priceModel===state.priceModel).map(p=>p.id),scenario:estimatePrice(result.prices.find(p=>p.id===state.calcId&&(state.priceModel==='all'||p.priceModel===state.priceModel)),state.quantity),assumption:'Single listed dimension; excludes other products, discounts, tax, implementation and undefined overages'};
  return result;
}
function toast(message){$('#biz-toast').textContent=message;setTimeout(()=>{if($('#biz-toast'))$('#biz-toast').textContent=''},3500)}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b||!data)return;
  if(b.dataset.view)setView(b.dataset.view);
  if(b.dataset.detail)showDetail(b.dataset.detail);
  if(b.dataset.company){state.filters={...DEFAULT_FILTERS,company:b.dataset.company};state.view='activity';state.limit=24;render()}
  if(b.dataset.type){state.filters.type=state.filters.type===b.dataset.type?'all':b.dataset.type;render()}
  if(b.dataset.analysisTopic){state.analysisTopic=b.dataset.analysisTopic;renderContent()}
  if(b.dataset.demandNeed){state.demandNeed=b.dataset.demandNeed;renderContent()}
  if(b.dataset.priceModel){state.priceModel=b.dataset.priceModel;renderContent()}
  if(b.dataset.mode){state.companyMode=b.dataset.mode;renderContent()}
  if(b.hasAttribute('data-reset')){state.demandNeed='all';state.priceModel='all';state.filters={...DEFAULT_FILTERS};state.limit=24;render()}
  if(b.hasAttribute('data-more')){state.limit+=24;renderContent()}
  if(b.hasAttribute('data-share')){try{await navigator.clipboard.writeText(location.href);toast(t('View link copied','已复制当前视图链接'))}catch{toast(t('Copy this page URL from the address bar.','可从地址栏复制当前视图链接。'))}}
  if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify(exportSelection(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='agent-safety-business-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  if(b.dataset.purposeEvidence){const ids=new Set(window.__bizPurposeEvidence?.[b.dataset.purposeEvidence]||[]),events=data.events.filter(r=>ids.has(r.id));show('<h2 id="ep-detail-title">'+t('Source rows for this purpose','此用途的源记录')+'</h2><p>'+t('Accounting labels only; no product or contract attribution.','仅按原文记账用途归类，未分摊到产品或合同。')+'</p><div class="biz-timeline">'+eventRows(events,events.length)+'</div>')}
  if(b.dataset.evidence){const ids=new Set(window.__bizFindingEvidence[b.dataset.evidence]||[]),events=data.events.filter(r=>ids.has(r.id)||ids.has(r.detailId));show('<h2 id="ep-detail-title">'+t('Evidence for this finding','这项观察的关联证据')+'</h2><p>'+events.length+' '+t('records in the selected scope','条当前范围内的记录')+'</p><div class="biz-timeline">'+eventRows(events,events.length)+'</div>')}
});
document.addEventListener('change',e=>{
  if(e.target.id==='biz-calc-price'){state.calcId=e.target.value;const price=data.prices.find(r=>r.id===state.calcId);state.quantity=['user','agent'].includes(price.priceModel)?500:100000;renderContent()}
});
document.addEventListener('input',e=>{
  if(e.target.id==='biz-calc-quantity'){state.quantity=e.target.value===''?NaN:Number(e.target.value);$('#biz-calc-output').innerHTML=scenarioMarkup(data.prices.find(r=>r.id===state.calcId),state.quantity,state.lang);history.replaceState(null,'',currentHash())}
});
window.addEventListener('hashchange',()=>{const route=parseRoute(location.hash);restoreAnalysis(new URLSearchParams(location.hash.split('?')[1]||''));state.view=validView(route.view)?route.view:'activity';state.filters=route.filters;state.limit=24;render()});
try{
  const response=await fetch('./data/business.json');
  if(!response.ok)throw Error('Business data unavailable');
  data=await response.json();ui=evidenceUI(data,state);render();
}catch(error){console.error(error);$('#app').innerHTML='<main class="error"><h1>产业数据暂时无法加载 / Data unavailable</h1><p>请刷新重试 / Please reload.</p><a href="./data/business.json">JSON</a> · <a href="./">Atlas</a></main>'}
